const crypto=require('crypto');
const secret=String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET||'').trim();
const url=String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL||'').trim();
if(secret.length<32)throw new Error('legacy_release_secret_not_configured');
if(!/\/api\/v1\/automation\/control\/receipt$/.test(url))throw new Error('legacy_release_control_url_invalid');
const id=String($execution.id||'').trim();
if(!id)throw new Error('legacy_release_execution_id_missing');
const body=JSON.stringify({schema_version:1,action:'CHECK_OR_REFRESH_LEGACY_GAME_RELEASES',game:'RIFTBOUND',execution_id:id.slice(0,120),occurred_at:new Date().toISOString()});
const timestamp=String(Math.floor(Date.now()/1000));
const signature='sha256='+crypto.createHmac('sha256',secret).update(timestamp+'.'+body,'utf8').digest('hex');
return [{json:{url:url.replace(/\/control\/receipt$/,'/commands/catalogue/check-legacy-game-releases'),body,timestamp,signature}}];

const response=$input.first().json||{};
const status=Number(response.statusCode||0);
if(status<200||status>=300)throw new Error('legacy_release_http_'+status);
const r=response.body||{};
if(r.accepted!==true||r.game!=='RIFTBOUND'||typeof r.execution_id!=='string')throw new Error('legacy_release_receipt_invalid');
if(r.artwork_published!==false||r.shopify_updated!==false||r.ownership_or_price_changed!==false)throw new Error('legacy_release_authority_violation');
if(!['CURRENT','COMPLETE','DEFERRED_CAPACITY','ALREADY_RUNNING','AWAITING_RIOT_APP_APPROVAL'].includes(r.status))throw new Error('legacy_release_action_required_'+String(r.status).slice(0,30));
if(r.status==='COMPLETE'&&(!Number.isInteger(r.source_imports)||r.source_imports<1))throw new Error('legacy_release_no_verified_import');
if(r.status==='DEFERRED_CAPACITY'&&typeof r.capacity_reason!=='string')throw new Error('legacy_release_capacity_receipt_missing');
if(r.status==='AWAITING_RIOT_APP_APPROVAL'&&r.game!=='RIFTBOUND')throw new Error('legacy_release_unknown_approval_state');
if(r.game==='RIFTBOUND'&&r.status!=='AWAITING_RIOT_APP_APPROVAL')throw new Error('riftbound_source_cannot_be_auto_approved');
return [{json:{game:r.game,status:r.status,sources_checked:r.sources_checked,source_imports:r.source_imports,capacity_reason:r.capacity_reason,metadata_updated:r.metadata_updated,artwork_published:false}}];
